#!/bin/sh
# What an archive needs that a checkout lacks: the app's submodules, LibTorrent's libtorrent
# project generated by cmake (boost from Homebrew), and a GoogleService-Info.plist. The plist is
# git-ignored; without a real one the app gets a placeholder, so Firebase (Crashlytics, Remote
# Config) stays off in that build. Safe to run again; `make testflight` runs it first.
set -eu
cd "$(dirname "$0")/.."

git submodule update --init --recursive Submodules
# make.sh asks for macOS 10.13, below what current Xcode accepts (12.0), and cmake's compiler
# check then fails; run it with 12.0 instead (its macOS slice is never shipped).
(cd Submodules/LibTorrent-Swift && sed 's/OSX_DEPLOYMENT_TARGET=10\.13/OSX_DEPLOYMENT_TARGET=12.0/' make.sh | zsh >/dev/null)

plist=iTorrent/Core/Assets/GoogleService-Info.plist
[ -f "$plist" ] || cat > "$plist" <<'PLIST'
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
	<key>API_KEY</key>
	<string>AIzaSyAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA</string>
	<key>GCM_SENDER_ID</key>
	<string>000000000000</string>
	<key>PLIST_VERSION</key>
	<string>1</string>
	<key>BUNDLE_ID</key>
	<string>dev.wobblygoat.magictv</string>
	<key>PROJECT_ID</key>
	<string>local-placeholder</string>
	<key>STORAGE_BUCKET</key>
	<string>local-placeholder.appspot.com</string>
	<key>IS_ADS_ENABLED</key>
	<false/>
	<key>IS_ANALYTICS_ENABLED</key>
	<false/>
	<key>IS_APPINVITE_ENABLED</key>
	<false/>
	<key>IS_GCM_ENABLED</key>
	<false/>
	<key>IS_SIGNIN_ENABLED</key>
	<false/>
	<key>GOOGLE_APP_ID</key>
	<string>1:000000000000:ios:0000000000000000000000</string>
</dict>
</plist>
PLIST
